const approvals = $('Get pending approvals').all().map(i => i.json).filter(a => a && a.id);
const invoices = $('Get invoices').all().map(i => i.json).filter(inv => inv && inv.id);

const dueSoon = invoices
  .filter(inv => Number(inv.toPay) > 0 && inv.dueInDays !== null && inv.dueInDays <= 7)
  .sort((a, b) => a.dueInDays - b.dueInDays);

const lines = [];
lines.push(`*Travel Code daily digest*`);
lines.push('');
lines.push(`:hourglass: *${approvals.length} request(s) waiting for your approval*`);
for (const a of approvals.slice(0, 10)) {
  lines.push(`• ${a.typeLabel} from ${a.requester?.name ?? 'unknown'} — ${a.createdAt}`);
}
lines.push('');
lines.push(`:receipt: *${dueSoon.length} invoice(s) due within 7 days*`);
for (const inv of dueSoon.slice(0, 10)) {
  const when = inv.dueInDays < 0 ? `overdue ${-inv.dueInDays} d` : `due in ${inv.dueInDays} d`;
  lines.push(`• ${inv.number} — ${inv.toPay} ${inv.currency} (${when})`);
}
if (approvals.length === 0 && dueSoon.length === 0) {
  lines.push('Nothing needs your attention today :tada:');
}
return [{ json: { text: lines.join('\n') } }];
